# Readable spacing in generated patient and clinician prose; identifiers/URLs unchanged.
import re
def readable(v):
 if isinstance(v,str):
  if v.startswith('http'):return v
  v=re.sub(r'\bNCCP(?=\d{5})','NCCP ',v)
  v=re.sub(r'\b(Day|Days|Week|Weeks|Grade|cycle|Cycle|cycles|Table|phase)(?=\d)',r'\1 ',v)
  v=re.sub(r'(?<=\d)(?=(?:days|day|weeks|week|hours|minutes|months|years|cycles|dose|and|mg|mL|micromol|xULN))',' ',v)
  v=re.sub(r'(?<=\d)(?=or|at|mg|m²)',' ',v)
  v=v.replace('andDay','and Day').replace('day8','day8').replace('stageII','stage II').replace('phaseII','phase II').replace('phaseIII','phase III').replace('IVvinorelbine','IV vinorelbine').replace('oralvinorelbine','oral vinorelbine').replace('daycycles','day cycles').replace('day cycle','day cycle')
  return v
 if isinstance(v,list):return [readable(x) for x in v]
 if isinstance(v,dict):return {k:v2 if k in ['id','code','protocol_id','source_ids','timeline_source_ids','support_source_ids','urgent_source_ids','script_id','schedule_kind','service_kind','source_url','url'] else readable(v2) for k,v2 in v.items()}
 return v
